INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('25d90855-e6c9-4d16-97a5-f188d0ed30d4', '21feff02-016d-46e2-bb9d-c27495133b1b', '80. óra: Létraverseny I.', 'Versenyszerű feladatmegoldás páros munkában az arányosságok témájában.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "aa8f2e3e-9772-40c8-8ea7-e552e2333e44", "text": "Ha 2 m szalag 400 Ft, mennyibe kerül 10 m szalag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "5083348e-707c-4f8a-8291-e8d5eb5b502e", "text": "Mennyi az 5 : 15 arány legegyszerűbb alakja?", "type": "multiple-choice", "options": [{"id": "3da0b675-b264-4ef3-b52a-27addbee745f", "text": "1 : 3", "isCorrect": true}, {"id": "9d38b2e6-d905-47fa-a250-9af2049abce7", "text": "1 : 5", "isCorrect": false}, {"id": "b1ea79a7-f05b-4831-b5c0-9e0b7c60a4be", "text": "3 : 1", "isCorrect": false}, {"id": "3b224ba8-23de-468a-afd6-37022e45ea57", "text": "1 : 2", "isCorrect": false}], "timeLimit": 15}, {"id": "329450d5-a98e-4935-b80b-5da0929f987d", "text": "Mennyi 200-nak a 3/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120"}, {"id": "9f077027-9512-409f-88b2-81b91a315ee8", "text": "Mi a sorozat 5. eleme: 3, 6, 12, 24, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "9acebda2-68e4-47f2-be24-94ada2f89373", "text": "Az arányos osztásnál a részek összege kiadja az eredeti egészet.", "type": "true-false", "options": [{"id": "ad94ac9b-098b-47ad-8b9f-d287be594141", "text": "Igaz", "isCorrect": true}, {"id": "19df9a16-7b42-4d69-97cc-e6e9b6a7f949", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "adb1b578-653b-4ad5-9f8a-be35851d50a1", "text": "Hány dl szörp kell 2 liter (1:4 arányú) hígított italhoz? (20 dl / 5 = 4 dl)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "1463a2ce-5114-46c5-bbea-884e23ffbd86", "text": "A játékos versenyzés növeli a feladatmegoldási motivációt.", "type": "true-false", "options": [{"id": "bd661757-5bbe-426a-912e-49ed127c4f01", "text": "Igaz", "isCorrect": true}, {"id": "ed8cc8c7-6f4d-4310-b2b2-a365cc510579", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('53ec8e46-3547-4ea1-87ce-9a43709e4881', '21feff02-016d-46e2-bb9d-c27495133b1b', '81. óra: Százalékszámítás', '1 egész = 100%, 1% fogalma (századrész), százalék és törtrész kapcsolata.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "6432b90c-59e2-473b-b269-a1f5cebe19a5", "text": "Mit jelent a 1% (egy százalék) fogalma?", "type": "multiple-choice", "options": [{"id": "65d95fd2-361f-4dc2-8d8e-13a34e4c5d86", "text": "Az egész mennyiség 1/100-ad részét (századrészét)", "isCorrect": true}, {"id": "19e1b46a-556a-40da-8e83-a9852f600b92", "text": "Az egész 1/10-ed részét", "isCorrect": false}, {"id": "408ec459-b1d1-4c70-9702-d9c76a7948e0", "text": "100 egészet", "isCorrect": false}, {"id": "3708fe71-871c-401a-bee5-29d78925d68f", "text": "Az egész felét", "isCorrect": false}], "timeLimit": 15}, {"id": "cb664f6d-3962-4751-9276-0cf0d45b0b63", "text": "Hány százalék felel meg a teljes egésznek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "4b002ed4-82cc-4761-a937-ede9a25adc7c", "text": "Hány százalék felel meg a fél (1/2) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "e8eb7ba2-d2a0-400d-ad6a-1b833d71cafa", "text": "Hány százalék felel meg a negyed (1/4) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "dc0fbc3b-5763-413a-b771-05d54a7ba002", "text": "Hány százalék felel meg a háromnegyed (3/4) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "75"}, {"id": "17209a23-f0d5-4b26-93a8-11ad198302c1", "text": "A 10% az egész 1/10-ed részét jelenti.", "type": "true-false", "options": [{"id": "ca356491-4067-40d0-a741-8e4d96bf26a5", "text": "Igaz", "isCorrect": true}, {"id": "4722659d-966f-40e9-b4b8-08fe3940a333", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c940eca2-d05c-4e02-9abe-82f8feb70047", "text": "A 20% az egész 1/5-öd részének felel meg.", "type": "true-false", "options": [{"id": "b3bad937-badd-4003-9467-465a3159034b", "text": "Igaz", "isCorrect": true}, {"id": "7f856688-3f4b-4dfc-a4b6-70fc57267e73", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1d2d5e31-f0aa-44eb-a240-677325033162', '21feff02-016d-46e2-bb9d-c27495133b1b', '82. óra: A százalékszámítás gyakorlása', 'Százalékérték kiszámítása következtetéssel (1% kiszámítása) vagy törtrésszel.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "c9c00ded-31f1-437e-88cb-e921b685e5e4", "text": "Mennyi 500 Ft-nak a 10%-a? (500 / 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "aba1dbd1-4c23-4d94-a6ab-c6f91d90ba33", "text": "Mennyi 500 Ft-nak az 1%-a? (500 / 100)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "7635e815-d4ae-484e-9fee-501164c5315c", "text": "Mennyi 500 Ft-nak a 20%-a? (500 * 0,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "54378d4a-3bc6-42ef-a222-ae6d41b2b03e", "text": "Mennyi 800 kg-nak az 50%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "d6258833-e0cf-4969-9b6b-ad58cca45eae", "text": "A százalékérték kiszámításához az alapmennyiséget megszorozzuk a százaléklábbal és elosztjuk 100-zal.", "type": "true-false", "options": [{"id": "6c4afa46-c5f2-4ccd-a439-c5623afa2420", "text": "Igaz", "isCorrect": true}, {"id": "bd26c044-0ad0-43af-a4f7-268ff6b50900", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2060ebd1-dc4d-4806-805e-7507fa899525", "text": "Mennyi 200 Ft-nak a 25%-a? (200 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "1d1535ca-5822-41c4-944c-e9611b43c139", "text": "Mennyi 1000 Ft-nak a 30%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e06c230c-745c-4f82-ae8a-fa5163702620', '21feff02-016d-46e2-bb9d-c27495133b1b', '83. óra: Feladatmegoldás', 'Százalékszámítással kapcsolatos hétköznapi szöveges feladatok.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "79a0a805-4c86-455b-9da1-65ccce19fd6d", "text": "Egy 10 000 Ft-os cipő árából 20% kedvezményt adnak. Mennyi a kedvezmény összege? (10000 * 0,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "e3b72c87-ca4b-4fd1-bf19-d2a70cf1a4ee", "text": "Egy 10 000 Ft-os cipő árából 20% kedvezményt adnak. Mennyi a kedvezményes ár? (10000 - 2000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8000"}, {"id": "9d15e913-ba35-4c3a-a810-5b0024b10203", "text": "Egy iskolában 400 tanuló van. 55%-uk lány. Hány lány jár az iskolába? (400 * 0,55)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "220"}, {"id": "d3ac4e4d-712e-4bfa-b129-8c85239626ef", "text": "Hány fiú jár az iskolába? (400 - 220)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "6d89789d-b615-4df8-a029-99529e80f4b9", "text": "A kedvezményes ár kiszámításához az eredeti árból kivonjuk a kedvezmény értékét.", "type": "true-false", "options": [{"id": "33db3fbd-19d5-457c-b5a5-e2fb61d5009d", "text": "Igaz", "isCorrect": true}, {"id": "284c203e-e18e-4f96-a93d-f1780fa1cbce", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "da18b45e-9981-4afa-9ab0-4434d3d79998", "text": "Ha egy ár 10%-kal nő, az új ár az eredeti ár 110%-a lesz.", "type": "true-false", "options": [{"id": "ef9e7833-1d3d-4ad0-913b-01b9fd297351", "text": "Igaz", "isCorrect": true}, {"id": "d56bb6cf-1665-43d7-980d-87a1a3485e51", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1ee0829e-b6e3-4c8a-9340-98ea4c6c50a5", "text": "Mennyi 50 000 Ft 5%-os kamata 1 évre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('36be8d08-8afb-46b5-bf98-9a5686f90c1c', '21feff02-016d-46e2-bb9d-c27495133b1b', '84. óra: Feladatmegoldás II.', 'Összetettebb százalékszámítási feladatok, árleértékelések, drágulások.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "ea322f08-46e5-4b29-89c1-19571ede1e7f", "text": "Egy 20 000 Ft-os kabát árát 15%-kal felemelték. Hány Ft a drágulás értéke? (20000 * 0,15)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3000"}, {"id": "cd35e7dc-0acf-41ab-9597-6d646882821b", "text": "Mennyi a kabát új ára a 15%-os drágulás után? (20000 + 3000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "23000"}, {"id": "a99e0c66-103b-4ba0-8498-d0b330d50a51", "text": "A 30-as létszámú osztályban a tanulók 10%-a hiányzott. Hány tanuló hiányzott?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "e4363a45-d5d4-4c47-8f68-f14bdf3051fb", "text": "Hány tanuló volt jelen az osztályban? (30 - 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "5acb5928-5f28-410f-8beb-bd8917207bfc", "text": "Ha a 100 Ft-os termék ára 50%-kal csökken, majd a kedvezményes ár 50%-kal nő, az ár visszatér 100 Ft-ra.", "type": "true-false", "options": [{"id": "a4d15462-26bc-40d3-9517-009c1abbb008", "text": "Igaz", "isCorrect": false}, {"id": "aed0dccc-cae2-463a-93d7-8cafc36f6e8b", "text": "Hamis (50 Ft 50%-os növekedése 75 Ft lesz!)", "isCorrect": true}], "timeLimit": 15}, {"id": "091f4cef-c70e-4d84-bb53-bd876c028fc1", "text": "Mennyi 400 liter 75%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "525e195b-2170-417c-b62a-d0e381a22eff", "text": "A százalékszámítás alapvető ismeret a mindennapi pénzügyi tájékozódáshoz.", "type": "true-false", "options": [{"id": "5a085b0a-2db3-4647-9453-44a38f6b1b15", "text": "Igaz", "isCorrect": true}, {"id": "4382569b-495c-4f6e-81b2-6b09fa0f45a0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('070264bb-dbc6-4b61-9bad-1623db2f7256', '21feff02-016d-46e2-bb9d-c27495133b1b', '85. óra: Projektóra', 'Családi költségvetés készítése megadott keretből, százalékos megoszlások számítása.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "77f16a22-0da9-4d34-a379-2b899b257fcd", "text": "Ha a család havi jövedelme 400 000 Ft, és 30%-ot költenek lakhatásra, hány Ft a lakhatási költség?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120000"}, {"id": "897e77b2-9924-46e2-b188-475c8a514ea3", "text": "Ha a jövedelem 40%-át élelmiszerre költik, hány Ft megy élelmiszerre? (400000 * 0,4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160000"}, {"id": "f6cc303f-a040-41c1-82e7-d6a40d38fbfc", "text": "Hány Ft marad megtakarításra és egyéb kiadásokra? (400000 - 120000 - 160000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120000"}, {"id": "b3a212db-8aa1-4d77-a210-76805777c546", "text": "A családi költségvetés készítésekor a kiadások összege nem haladhatja meg a bevételeket.", "type": "true-false", "options": [{"id": "79442d90-ad4d-4c50-aeba-d87ba5e042d0", "text": "Igaz", "isCorrect": true}, {"id": "175b36b8-089c-4c36-9b65-7b109e7e71f4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "90c8fea7-1a79-434b-8e03-916312cfbbfe", "text": "Hány százalékot tesz ki a megmaradt 120 000 Ft a 400 000 Ft-os jövedelemből?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "9efb6434-34be-4746-86e7-cc44bbc6b166", "text": "A százalékos megoszlás kördiagramon ábrázolva jól szemlélteti a kiadások arányát.", "type": "true-false", "options": [{"id": "95f10a75-46a4-4077-a93f-20ca13f0177f", "text": "Igaz", "isCorrect": true}, {"id": "f1fdd395-0c40-4c53-99b8-b35064a1b5df", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9bc2d3ea-779b-4d87-974a-a787b1df4d56", "text": "A tudatos pénzügyi tervezés segít elkerülni az eladósodást.", "type": "true-false", "options": [{"id": "c7e4f5b6-2f72-4079-87fc-aa2b59de7b67", "text": "Igaz", "isCorrect": true}, {"id": "80a0e698-19bc-49fe-9752-c868e9948c8c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('58c4b21c-1429-4dbe-80cc-b0c397b9bb1d', '21feff02-016d-46e2-bb9d-c27495133b1b', '86. óra: Nyitott mondatok', 'Lebontogatás (visszafelé gondolkodás) és próbálgatás módszere egyenleteknél.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "8f1c82ed-611a-4903-9508-cc5a8c5311ad", "text": "Mit jelent a lebontogatás (visszafelé gondolkodás) módszere?", "type": "multiple-choice", "options": [{"id": "642e25c5-0552-4e60-a18d-e5264a39d2ef", "text": "A végeredményből kiindulva az inverz (ellentétes) műveleteket végezzük el visszafelé", "isCorrect": true}, {"id": "a9948fec-f487-4739-9aec-badf4858f187", "text": "Visszafelé írjuk le a számokat", "isCorrect": false}, {"id": "51a30511-36f3-4031-bb8e-02a6ea258fec", "text": "Tippelünk egy számot és feladjuk", "isCorrect": false}, {"id": "f764e655-bf31-4680-89b0-2380263ebcd5", "text": "Kivonunk mindent 100-ból", "isCorrect": false}], "timeLimit": 15}, {"id": "ba834317-f278-47ed-ab8c-c2d6e102cbc7", "text": "Melyik szám teszi igazzá: 2 * x + 5 = 17? (17 - 5 = 12, 12 / 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "5938c20a-24a2-48e9-aff5-f482281cee06", "text": "Melyik szám teszi igazzá: (y - 4) : 3 = 5? (5 * 3 = 15, 15 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "19"}, {"id": "127cd6aa-2601-448d-b08a-d63227ed8351", "text": "Az ellenőrzés során a kapott értéket behelyettesítjük az eredeti nyitott mondatba.", "type": "true-false", "options": [{"id": "ee8053f1-0855-4591-9c12-db3918c05995", "text": "Igaz", "isCorrect": true}, {"id": "d860a04d-63e0-4dd6-b764-caca68b67656", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e30853f5-dabe-47ed-9d57-af4decbe13bc", "text": "Melyik szám teszi igazzá: 3 * a - 10 = 20?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "c9f46b49-c819-429e-b7dc-60056ce3251c", "text": "A próbálgatásos módszernél rendszerezett táblázatot érdemes vezetni.", "type": "true-false", "options": [{"id": "fa6f5841-a1df-4180-9e01-b5d15f6a06b2", "text": "Igaz", "isCorrect": true}, {"id": "91d3e602-4540-4142-a2c5-61e33ba65bda", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c762c50f-2604-45ba-9902-b7d36a248525", "text": "Melyik szám teszi igazzá: x / 4 + 2 = 7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d656af41-43f2-4ce3-b16c-4f3fc51193fb', '21feff02-016d-46e2-bb9d-c27495133b1b', '87. óra: Feladatmegoldás: Nyitott mondatok', 'Gyakorlás: lebontogatási módszer alkalmazása egyenletek és egyenlőtlenségek megoldásában.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "4e86cfb1-1a1b-486a-a07c-7d059a32b1e5", "text": "Melyik szám teszi igazzá: 4 * (x + 2) = 36? (36/4 = 9, 9-2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "6ca9c2e9-105e-49d1-83cf-0baa99b49aba", "text": "Melyik szám teszi igazzá: 5 * y - 12 = 38? (50/5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "c24dc0d7-14ac-4aa8-9af4-9d0b884a5dae", "text": "Ha az alaphalmaz a természetes számok (0, 1, 2, ...), hány megoldása van a 2 * x < 6 egyenlőtlenségnek? (x = 0, 1, 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "82086de0-4db7-4c89-8f56-c5ef6cef43ae", "text": "Az egyenlőtlenségeknek több megoldása is lehet egy megadott alaphalmazon.", "type": "true-false", "options": [{"id": "d30898d6-e548-431f-9a11-be50ea78397a", "text": "Igaz", "isCorrect": true}, {"id": "9d9f4f62-f698-4a8d-8437-4f18bbe23a2f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c9f921d3-add9-4c52-9c6c-25b7b7994deb", "text": "Melyik szám teszi igazzá: (z + 10) / 2 = 15?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "123be599-da1f-4e51-b98c-a5dd48233fa4", "text": "Ha az egyenletnek nincs megoldása az adott alaphalmazon, az igazsághalmaz az üres halmaz.", "type": "true-false", "options": [{"id": "ef669664-0c74-4f01-a354-32acca520e5f", "text": "Igaz", "isCorrect": true}, {"id": "3d2b9650-fc77-4d9f-bedb-94a0884977ca", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "781a16b2-e2fd-44f2-a160-cefa22c90caf", "text": "Melyik szám teszi igazzá: 10 * x - 25 = 75?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('74d8c7fb-4da2-4fc5-8481-58ba32f7cb35', '21feff02-016d-46e2-bb9d-c27495133b1b', '88. óra: Gyakorlóóra', 'Nyitott mondatok és műveleti sorrend gyakorlása.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "68146811-1a59-47af-bd0c-b8c14f5b6782", "text": "Melyik szám teszi igazzá: 3 * x + 7 = 34?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "2135aa12-612e-46a7-a843-a91212352b52", "text": "Melyik szám teszi igazzá: (x - 5) * 6 = 42?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "9bd9c388-2043-4a9f-9b3a-9a47eeaf9af9", "text": "A lebontogatás lépései során az utolsóként elvégzett művelet inverzével kezdjük a számolást.", "type": "true-false", "options": [{"id": "325e335d-65aa-4a9a-92fe-bcaed4513796", "text": "Igaz", "isCorrect": true}, {"id": "706a2d50-3fd7-47d3-975a-f86c24c5e640", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2b887d1e-3e78-445f-bb34-d15dbf106071", "text": "Mennyi x értéke, ha 50 - 2 * x = 30? (2x = 20)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "9b383b9d-1f80-4846-92f7-dd5dd41e2e35", "text": "Mennyi y értéke, ha y / 3 - 4 = 6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "381de9be-2623-4ac1-a4b5-691055fe5a15", "text": "Az ellenőrzés kihagyása növeli a hibázás kockázatát.", "type": "true-false", "options": [{"id": "2989779b-0352-44e6-aac9-0beeb10fd2a1", "text": "Igaz", "isCorrect": true}, {"id": "500149f8-8200-425c-b9a0-3cbdc37075af", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e08b767b-c0c5-430a-a327-f9ac74aab045", "text": "Melyik szám teszi igazzá: 8 * a + 4 = 68?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4d7ae785-c60e-4357-a15c-8b4e2f52611b', '21feff02-016d-46e2-bb9d-c27495133b1b', '89. óra: Szöveges feladatok', 'Szöveges feladatok megoldása nyitott mondatok felírásával, ábrakészítéssel.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "29d607c9-9864-4569-8be2-1c86e3ff85b2", "text": "Gondoltam egy számot, megszóroztam 3-mal, hozzáadtam 12-őt és 45-öt kaptam. Mi volt a szám? (3x + 12 = 45 -> 3x = 33)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "6d14efb5-1305-462c-a186-c85f5b169ce8", "text": "Gondoltam egy számot, kivontam belőle 8-at, megszoroztam 4-gyel és 40-et kaptam. Mi volt a szám? ((x-8)*4 = 40 -> x-8 = 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "b3f83748-524f-483f-98d0-f604a88e4737", "text": "Katinak 3-szor annyi matricája van, mint Petinek. Összesen 48 matricájuk van. Hány matricája van Petinek? (x + 3x = 48 -> 4x = 48)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "b325a23c-4805-48dd-a725-a22308e2b252", "text": "Hány matricája van Katinak? (3 * 12)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "00c25081-c8d7-4bac-903c-5631163b651f", "text": "A szöveges feladatok megoldásának lépései: Értelmezés -> Adatok/Ismeretlen -> Nyitott mondat -> Számolás -> Ellenőrzés -> Válaszmondat.", "type": "true-false", "options": [{"id": "040b284d-dad9-4200-8892-1e94cb73f6f3", "text": "Igaz", "isCorrect": true}, {"id": "944f0298-0483-41e9-85c9-f63403421460", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c1aa7171-3203-4905-a856-a6058584c1ad", "text": "Ha a feladatban a ''kétszer annyi'' kifejezés szerepel, 2-vel való szorzásra gondolunk.", "type": "true-false", "options": [{"id": "ba66ebf4-d095-4d91-ae1e-3599020572a2", "text": "Igaz", "isCorrect": true}, {"id": "4646ec29-363f-433d-ad1d-ca0d7c096d17", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "253e9bf9-26d3-4588-92f3-5dfd84064c51", "text": "Gondoltam egy számot, elosztottam 5-tel, hozzáadtam 7-et és 12-őt kaptam. Mi a szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}]'::jsonb, true, NOW());